        ("folk", "trade", ["That's a fair deal.", "Pleasure doing business.", "You drive a hard bargain.", "Thank you kindly.", "Done and done."]),
        ("folk", "broke", ["Not enough there, I'm afraid.", "Counting's not your strong suit, is it?", "That won't cover it.", "Bit light in the purse today?"]),
        ("folk", "theft", ["Hey! That's not yours!", "I saw that. Hand it back.", "Thief! Somebody get the sheriff!", "Put it down, or I'll holler."]),
        ("folk", "angry", ["You've got some nerve!", "Get away from me!", "I'll remember your face!", "Somebody help! He's trouble!"]),
