        ("folk", "raid", ["Raiders on the road! Get inside!", "Bar the doors! They're coming!", "Hide the children!", "Somebody ring the bell!"]),

        // MARK: Shopkeepers
        ("keeper", "greet", ["Welcome! Everything you see is for sale. Except the cat.", "Come in, come in. Mind the step.", "Good to see you. Looking for anything special?",
