        ("keeper", "broke", ["I can't give it away, friend.", "Come back with a bit more coin.", "Credit's not something I do. Sorry.",
                             "That's a little under, I'm afraid."]),
        ("keeper", "theft", ["You pay for that first!", "That stays on the shelf!", "I saw that go in your pocket!", "That's coming out of your hide!"]),
        ("keeper", "angry", ["Out! Get out of my shop!", "You're not welcome here anymore!", "I'm calling the sheriff!"]),
        ("keeper", "hurt", ["Ow! Not in my shop!", "Help! I'm being robbed!", "Stop it! Take what you want!"]),
        ("keeper", "handsup", ["Take the till, just don't shoot!", "Easy, it's all yours!", "I'm not armed! I'm just a shopkeeper!"]),
        ("keeper", "closed", ["We're shut. Opens at sunup.", "Sorry, closed for the night.", "Try me tomorrow, I'm done in.", "Door's locked. Come back in the morning."]),
        ("keeper", "raid", ["Lock the shop! Raiders!", "Hide the stock! They're coming!", "Not my shop! Not again!"]),

        // MARK: Saloon and butcher
        ("chef", "greet", ["Sit down, sit down. Stew's hot.", "Welcome! Hungry? You look hungry.", "Pull up a stool. What'll it be?",
