        ("chef", "bye", ["Bring your appetite next time!", "Don't let the door hit you.", "Good night, eat well.", "Next one's on... well, you."]),
        ("chef", "trade", ["Eat up before it cools.", "Fresh as it gets.", "That'll stick to your ribs.", "Coming right up."]),
        ("chef", "broke", ["No coin, no supper.", "Kitchen doesn't run on promises.", "Come back when your pockets jingle."]),
        ("chef", "theft", ["That plate's not paid for!", "Hey! Put down my pie!", "Thief in the kitchen!"]),
        ("chef", "angry", ["Get out of my kitchen!", "You're barred! Out!", "I've got a cleaver and I know how to use it!"]),
        ("chef", "hurt", ["Ow! Watch it!", "Help! Somebody stop him!", "Not the face! I need the face!"]),
        ("chef", "handsup", ["Take the money! Leave the stew!", "Easy now! I just cook!"]),
        ("chef", "closed", ["Kitchen's cold. Try tomorrow.", "We're shut, friend. Ovens are out.", "No more food tonight."]),
