        ("farmer", "angry", ["Off my land!", "I've got a pitchfork and nothing to lose!"]),
        ("farmer", "hurt", ["Ow! Leave me be!", "Help! Up at the farm!"]),
        ("farmer", "handsup", ["Easy! Take the eggs!", "I'm just a farmer, mister!"]),
        ("farmer", "raid", ["Raiders in the fields! Run!", "Get the animals in! Now!"]),

