        ("elder", "raid", ["Raiders again! Like the old days!", "Get the young ones inside!"]),

        // MARK: Deputies
        ("deputy", "greet", ["Afternoon. Keep it peaceful.", "Howdy. Sheriff's around if you need him.", "You new? Rules are simple. Don't break anything.",
                             "Hello. Weapons stay holstered in town.", "Good day. Staying long?", "Evening. Any trouble on the road?"]),
        ("deputy", "chatter", ["Quiet day. Too quiet.", "Paperwork. All day, paperwork.", "Arrested a goat this morning. Long story.",
